 * @notice Interface for share token operations in the vault
 * @dev Provides functions for minting, burning, and managing share tokens
 */
interface IShareToken {
    function mint(address to, uint256 amount) external;
    function burn(address from, uint256 amount) external;
    function spendAllowance(address owner, address caller, uint256 shares) external;
    function nativeApprove(address owner, address spender, uint256 amount) external returns(bool);
    function nativeTransfer(address owner, address to, uint256 amount) external returns (bool);
    function nativeTransferFrom(address spender, address from, address to, uint256 amount) external returns (bool);
}

/**
 * @title IOracle
 * @notice Interface for price oracle functionality
 * @dev Provides conversion functions between assets and shares
 */
interface IOracle {
    function convertToShares(address token, uint256 assets) external view returns (uint256);
    function convertToAssets(address token, uint256 shares) external view returns (uint256);
}

/**
