    function __ERC4626_init(IERC20Upgradeable asset_, IERC20Upgradeable share_, address oracle_) internal onlyInitializing {
        __ERC4626_init_unchained(asset_, share_, oracle_);
    }

    function __ERC4626_init_unchained(IERC20Upgradeable asset_, IERC20Upgradeable share_, address oracle_) internal onlyInitializing {
        (bool success, uint8 assetDecimals) = _tryGetAssetDecimals(asset_);
        _underlyingDecimals = success ? assetDecimals : 18;
        _asset = asset_;
        _share = share_;
        oracle = oracle_;
    }

    /**
     * @dev Attempts to fetch the asset decimals. A return value of false indicates that the attempt failed in some way.
     */
    function _tryGetAssetDecimals(IERC20Upgradeable asset_) private view returns (bool, uint8) {
        (bool success, bytes memory encodedDecimals) = address(asset_).staticcall(
            abi.encodeWithSelector(IERC20MetadataUpgradeable.decimals.selector)
        );
        if (success && encodedDecimals.length >= 32) {
            uint256 returnedDecimals = abi.decode(encodedDecimals, (uint256));
            if (returnedDecimals <= type(uint8).max) {
                return (true, uint8(returnedDecimals));
            }
        }
        return (false, 0);
    }

    /**
     * @dev Decimals are computed by adding the decimal offset on top of the underlying asset's decimals. This
     * "original" value is cached during construction of the vault contract. If this read operation fails (e.g., the
     * asset has not been created yet), a default of 18 is used to represent the underlying asset's decimals.
     *
     * See {IERC20Metadata-decimals}.
     */
    function decimals() public view virtual returns (uint8) {
        return _underlyingDecimals + _decimalsOffset();
    }

    /** @dev See {IERC4626-asset}. */
    function asset() public view virtual override returns (address) {
        return address(_asset);
    }

    /** @dev See {IERC4626-totalAssets}. */
    function totalAssets() public view virtual override returns (uint256) {
        return _asset.balanceOf(address(this));
    }

    /** @dev See {IERC4626-convertToShares}. */
    function convertToShares(uint256 assets) public view virtual override returns (uint256) {
        return _convertToShares(assets);
    }

    /** @dev See {IERC4626-convertToAssets}. */
    function convertToAssets(uint256 shares) public view virtual override returns (uint256) {
        return _convertToAssets(shares);
    }

    /** @dev See {IERC4626-maxDeposit}. */
    function maxDeposit(address) public view virtual override returns (uint256) {
        return type(uint256).max;
    }

    /** @dev See {IERC4626-maxMint}. */
    function maxMint(address) public view virtual override returns (uint256) {
        return type(uint256).max;
    }

    /** @dev See {IERC4626-maxWithdraw}. */
    function maxWithdraw(address owner) public view virtual override returns (uint256) {
        return _convertToAssets(_share.balanceOf(owner));
    }

    /** @dev See {IERC4626-maxRedeem}. */
    function maxRedeem(address owner) public view virtual override returns (uint256) {
        return _share.balanceOf(owner);
    }

    /** @dev See {IERC4626-previewDeposit}. */
    function previewDeposit(uint256 assets) public view virtual override returns (uint256) {
        return _convertToShares(assets);
    }

    /** @dev See {IERC4626-previewMint}. */
    function previewMint(uint256 shares) public view virtual override returns (uint256) {
        return _convertToAssets(shares);
    }

    /** @dev See {IERC4626-previewWithdraw}. */
    function previewWithdraw(uint256 assets) public view virtual override returns (uint256) {
        return _convertToShares(assets);
    }

    /** @dev See {IERC4626-previewRedeem}. */
    function previewRedeem(uint256 shares) public view virtual override returns (uint256) {
        return _convertToAssets(shares);
    }

    /** @dev See {IERC4626-deposit}. */
    function deposit(uint256 assets, address receiver) public virtual override returns (uint256) {
        require(assets <= maxDeposit(receiver), "ERC4626: deposit more than max");

        uint256 shares = previewDeposit(assets);
        _deposit(_msgSender(), receiver, assets, shares);

        return shares;
    }

    /** @dev See {IERC4626-mint}.
     *
     * As opposed to {deposit}, minting is allowed even if the vault is in a state where the price of a share is zero.
     * In this case, the shares will be minted without requiring any assets to be deposited.
     */
    function mint(uint256 shares, address receiver) public virtual override returns (uint256) {
        require(shares <= maxMint(receiver), "ERC4626: mint more than max");

        uint256 assets = previewMint(shares);
        _deposit(_msgSender(), receiver, assets, shares);

        return assets;
    }

    /** @dev See {IERC4626-withdraw}. */
    function withdraw(uint256 assets, address receiver, address owner) public virtual override returns (uint256) {
        require(assets <= maxWithdraw(owner), "ERC4626: withdraw more than max");

        uint256 shares = previewWithdraw(assets);
        _withdraw(_msgSender(), receiver, owner, assets, shares);

        return shares;
    }

    /** @dev See {IERC4626-redeem}. */
    function redeem(uint256 shares, address receiver, address owner) public virtual override returns (uint256) {
        require(shares <= maxRedeem(owner), "ERC4626: redeem more than max");

        uint256 assets = previewRedeem(shares);
        _withdraw(_msgSender(), receiver, owner, assets, shares);

        return assets;
    }

    /**
     * @dev Internal conversion function (from assets to shares) with support for rounding direction.
     */
    function _convertToShares(uint256 assets) internal view virtual returns (uint256) {
        return IOracle(oracle).convertToShares(address(_asset), assets);
    }

    /**
     * @dev Internal conversion function (from shares to assets) with support for rounding direction.
     */
    function _convertToAssets(uint256 shares) internal view virtual returns (uint256) {
        return IOracle(oracle).convertToAssets(address(_asset), shares);
    }

    /**
     * @dev Deposit/mint common workflow.
     */
    function _deposit(address caller, address receiver, uint256 assets, uint256 shares) internal virtual {
        // If _asset is ERC777, `transferFrom` can trigger a reentrancy BEFORE the transfer happens through the
        // `tokensToSend` hook. On the other hand, the `tokenReceived` hook, that is triggered after the transfer,
        // calls the vault, which is assumed not malicious.
        //
        // Conclusion: we need to do the transfer before we mint so that any reentrancy would happen before the
        // assets are transferred and before the shares are minted, which is a valid state.
        // slither-disable-next-line reentrancy-no-eth
        SafeERC20Upgradeable.safeTransferFrom(_asset, caller, address(this), assets);
        IShareToken(address(_share)).mint(receiver, shares);
        emit Deposit(caller, receiver, assets, shares);
    }

    /**
     * @dev Withdraw/redeem common workflow.
     */
    function _withdraw(
        address caller,
        address receiver,
        address owner,
        uint256 assets,
        uint256 shares
    ) internal virtual {
        if (caller != owner) {
            IShareToken(address(_share)).spendAllowance(owner, caller, shares);
        }

        // If _asset is ERC777, `transfer` can trigger a reentrancy AFTER the transfer happens through the
        // `tokensReceived` hook. On the other hand, the `tokensToSend` hook, that is triggered before the transfer,
        // calls the vault, which is assumed not malicious.
        //
        // Conclusion: we need to do the transfer after the burn so that any reentrancy would happen after the
        // shares are burned and after the assets are transferred, which is a valid state.
        IShareToken(address(_share)).burn(owner, shares);
        SafeERC20Upgradeable.safeTransfer(_asset, receiver, assets);

        emit Withdraw(caller, receiver, owner, assets, shares);
    }

    function _decimalsOffset() internal view virtual returns (uint8) {
        return 0;
    }

    /**
     * @dev This empty reserved space is put in place to allow future versions to add new
     * variables without shifting down storage in the inheritance chain.
     * See https://docs.openzeppelin.com/contracts/4.x/upgradeable#storage_gaps
     */
    uint256[49] private __gap;
}

contracts/v3/CsigmaERC7575Vault.sol.content:
// SPDX-License-Identifier: BUSL-1.1
// @author cSigma Finance Inc., a Delaware company, for its Real World Credit tokenization protocol

pragma solidity 0.8.26;

import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/PausableUpgradeable.sol";
import "@openzeppelin/contracts/proxy/ERC1967/ERC1967Proxy.sol";
import "./CsigmaERC4626.sol";
import "./CsigmaV3WithdrawalManager.sol";

error PoolIsNotActive();
error InvalidPoolSize(uint256 _poolSize);
error InvalidStatusUpdate();
error AccessDenied(address _executor);
error WithdrawalPending();
error InvalidDepositAmount(uint256 _assets);
error InvalidAddress(address _newImpl);

/// @title FundManager
/// @notice This interface is used to get the total assets managed by the fund manager
interface FundManager {
    function totalAssets(address _token) external view returns (uint256);
}

/// @title WithdrawManager Interface
/// @notice Interface for withdrawal manager contracts that handle LP token withdrawal queues
interface WithdrawManager {
    function totalDueLPToken() external view returns (uint256);
    function repay(uint256 _queuePosition, uint256 _amount) external;
}

/// @title CsigmaV3Pool
/// @notice ERC-4626 compliant vault for managing tokenized real-world credit pools
/// @dev Implements upgradeable proxy pattern with access control, pausability, and withdrawal management
contract CsigmaV3Pool is
    Initializable,
    AccessControlUpgradeable,
    UUPSUpgradeable,
    PausableUpgradeable,
    ERC4626Upgradeable
{
    /// @notice Role identifier for oracle managers who can update AUM values
    bytes32 public constant ROLE_ORACLE_MANAGER = keccak256("ROLE_ORACLE_MANAGER");
    
    /// @notice Role identifier for pool managers who can perform operational functions
    bytes32 public constant ROLE_MANAGER = keccak256("ROLE_MANAGER");    
    
    /// @notice Address of the share token contract (csUSD)
    /// @dev Used for ERC-20 operations on vault shares
    address public share;
    
    /// @notice Percentage of deposits not held in reserve (sent to fund manager)
    /// @dev Expressed in basis points (e.g., 9500 = 95%)
    uint64 public nonReservePercentage;
    
    /// @notice Address of the pool manager
    /// @dev Has administrative privileges for pool operations
    address public poolManager;
    
    /// @notice Duration of daily pause window in seconds
    /// @dev During this window, certain operations are restricted
    uint64 public pauseDuration;
    
    /// @notice Address of the fund manager contract
    /// @dev Manages assets deployed outside the vault
    address public fundManager;
    
    /// @notice Start time of daily pause window (seconds from midnight)
    /// @dev Used to calculate when pause window is active
    uint64 public pauseStartTime;
    
    /// @notice Address of the underlying pool token (asset)
    /// @dev The ERC-20 token that the vault accepts as deposits
    address public poolToken;
    
    /// @notice Current status of the pool
    /// @dev Can be PENDING, ACTIVE, or CLOSE
    PoolStatus public status;
    
    /// @notice Timestamp when AUM was last updated
    /// @dev Used to enforce cooldown periods between AUM updates
    uint64 public AUMLastUpdatedAt;
    
    /// @notice Address of the withdrawal manager contract
    /// @dev Handles queued withdrawals when liquidity is insufficient
    address public withdrawalManager;
    
    /// @notice Threshold percentage for AUM changes
    /// @dev Expressed as basis points above 10000 (e.g., 10008 = 0.08% threshold)
    uint64 public AUMChangeThresholdPercentage;
    
    /// @notice Implementation address for withdrawal manager proxy
    /// @dev Used when creating new withdrawal manager instances
    address public withdrawalManagerImplementation;
    
    /// @notice Cooldown period between AUM updates in seconds
    /// @dev Prevents frequent AUM updates that could be manipulated
    uint64 public AUMUpdateCooldownPeriod;
    
    /// @notice Current assets under management by institutional vaults
    /// @dev Added to vault balance and fund manager balance for total assets
    uint256 public assetUnderManagement;

    /// @notice Possible states of the pool lifecycle
    /// @dev PENDING: Pool created but not active for deposits
    /// @dev ACTIVE: Pool accepting deposits and withdrawals
    /// @dev CLOSE: Pool closed, no new operations allowed
    enum PoolStatus {PENDING, ACTIVE, CLOSE}
    
    /// @notice Emitted when an oracle manager is added
    /// @param _account The address that was granted oracle manager role
    event OracleManagerAdded(address _account);
    
    /// @notice Emitted when an oracle manager is removed
    /// @param _account The address that lost oracle manager role
    event OracleManagerRemoved(address _account);
    
    /// @notice Emitted when admin role is transferred
    /// @param _oldOwner The previous admin address
    /// @param _newOwner The new admin address
    event AdminTransferred(address _oldOwner, address _newOwner);
    
    /// @notice Emitted when pool status changes
    /// @param _by The address that initiated the status change
    /// @param _prevStatus The previous pool status
    /// @param _newStatus The new pool status
    event PoolStatusUpdated(address indexed _by, PoolStatus _prevStatus, PoolStatus _newStatus);
    
    /// @notice Emitted when assets under management value is updated
    /// @param _by The address that updated the AUM
    /// @param _prevValue The previous AUM value
    /// @param _newValue The new AUM value
    event AssetUnderManagementUpdated(address indexed _by, uint256 _prevValue, uint256 _newValue);
    
    /// @notice Emitted when emergency withdrawal is performed
    /// @param _token The token that was withdrawn
    /// @param _to The recipient of the withdrawal
    /// @param _amount The amount withdrawn
    event EmergencyWithdraw(address _token, address _to, uint256 _amount);
    
    /// @notice Emitted when reserve funds are sent to fund manager
    /// @param _fundManager The fund manager receiving the funds
    /// @param _amount The amount sent
    event SendReserveToFundManager(address _fundManager, uint256 _amount);
    
    /// @notice Emitted when a new withdrawal manager is created
    /// @param _withdrawalManager The address of the created withdrawal manager
    /// @param _pool The pool associated with the withdrawal manager
    event WithdrawalManagerCreated(address indexed _withdrawalManager, address indexed _pool);

    /// @notice Ensures function is not called during the default pause window
    /// @dev Checks current time against pause start time and duration
    modifier whenNotInDefaultPauseWindow() {
        _requireNotInDefaultPauseWindow();
        _;
    }
    
    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @notice This function is used to initialize the contract
    /// @param _share The address of the share token contract (csUSD)
    /// @param _poolManager The address of the pool manager
    /// @param _fundManager The address of the fund manager
    /// @param _manager The address of the ops manager multisig 
    /// @param _poolToken The address of the pool token
    /// @param _assetOracle The address of the asset oracle contract 
    /// @param _oracleManager The address of the oracle manager
    function initialize(
        address _share,
        address _poolManager,
        address _fundManager,
        address _manager,
        address _poolToken,
        address _assetOracle,
        address _oracleManager
    )
        public
        initializer
    {
        __AccessControl_init();
        __UUPSUpgradeable_init();
        __Pausable_init();
        __ERC4626_init(IERC20Upgradeable(_poolToken), IERC20Upgradeable(_share), _assetOracle);
        
        _grantRole(DEFAULT_ADMIN_ROLE, _msgSender());
        _grantRole(ROLE_ORACLE_MANAGER, _oracleManager);
        _grantRole(ROLE_ORACLE_MANAGER, _fundManager);
        _grantRole(ROLE_MANAGER, _manager);
        share = _share;
        poolManager = _poolManager;
        fundManager = _fundManager;
        poolToken = _poolToken;
        AUMChangeThresholdPercentage = 10008;
        AUMUpdateCooldownPeriod = 2 hours;
        nonReservePercentage = 9500;
        pauseDuration = 2700;
    }

    /// @notice Returns true if the contract supports a given interface
    /// @param interfaceId Interface identifier (ERC-165, ERC-7575)
    function supportsInterface(bytes4 interfaceId) public view virtual override returns (bool) {
        return interfaceId == 0x2f0a18c5 || interfaceId == 0x01ffc9a7;
	}

    /// @notice This function is used to get the total amount of the underlying asset that is “managed” by Vault
    /// @return The total assets
    function totalAssets() public view virtual override returns (uint256) {
        return (IERC20Upgradeable(poolToken).balanceOf(address(this)) + FundManager(fundManager).totalAssets(poolToken) + assetUnderManagement);
    }

    /// @notice This function returns the maximum amount of assets that can be withdrawn
    /// @return The maximum amount of assets
    function maxWithdraw(address) public view virtual override returns (uint256) {
        return IERC20Upgradeable(poolToken).balanceOf(address(this));
    }

    /// @notice This function returns the maximum amount of shares that can be redeemed
    /// @return The maximum amount of shares
    function maxRedeem(address) public view virtual override returns (uint256) {
        return _convertToShares(maxWithdraw(address(0)));
    }

    /// @notice This function is used to deposit the assets
    /// @param assets The amount of assets to deposit
    /// @param receiver The address of the receiver
    /// @return shares The amount of shares minted
    function deposit(uint256 assets, address receiver) public virtual override whenNotPaused whenNotInDefaultPauseWindow returns (uint256 shares) {
        if(status != PoolStatus.ACTIVE) revert PoolIsNotActive();
        shares = super.deposit(assets, receiver);
        SafeERC20Upgradeable.safeTransfer(IERC20Upgradeable(poolToken), fundManager, (assets * nonReservePercentage) / 10000);
    }

    /// @notice This function is used to mint the shares
    /// @param shares The amount of shares to mint
    /// @param receiver The address of the receiver
    /// @return assets The amount of assets used to mint the shares
    function mint(uint256 shares, address receiver) public virtual override whenNotPaused whenNotInDefaultPauseWindow returns (uint256 assets) {
        if(status != PoolStatus.ACTIVE) revert PoolIsNotActive();
        assets = super.mint(shares, receiver);
        SafeERC20Upgradeable.safeTransfer(IERC20Upgradeable(poolToken), fundManager, (assets * nonReservePercentage) / 10000);
    }

    /// @notice This function is used to withdraw the assets
    /// @param assets The amount of assets to withdraw
    /// @param receiver The address of the receiver
    /// @param owner The address of the owner of the assets
    /// @return The amount of shares burned
    function withdraw(uint256 assets, address receiver, address owner) public virtual override whenNotPaused whenNotInDefaultPauseWindow returns (uint256) {
        if(status != PoolStatus.ACTIVE) revert PoolIsNotActive();
        return super.withdraw(assets, receiver, owner);
    }

    /// @notice This function is used to redeem the shares
    /// @param shares The amount of shares to redeem
    /// @param receiver The address of the receiver
    /// @param owner The address of the owner of the shares
    /// @return The amount of assets redeemed
    function redeem(uint256 shares, address receiver, address owner) public virtual override whenNotPaused whenNotInDefaultPauseWindow returns (uint256) {
        if(status != PoolStatus.ACTIVE) revert PoolIsNotActive();
        return super.redeem(shares, receiver, owner);
    }

    /// @notice This function is used to update the pool manager
    /// @dev Only the admin can call this function
    /// @param _poolManager The address of the new pool manager
    function updatePoolManager(address _poolManager) external onlyRole(DEFAULT_ADMIN_ROLE) {
        poolManager = _poolManager;
    }

    /// @notice This function is used to update the status of the pool from pending to active
    /// @dev Only the pool manager can call this function
    function activatePool() external whenNotPaused whenNotInDefaultPauseWindow onlyRole(ROLE_MANAGER) {
        if(status != PoolStatus.PENDING) revert InvalidStatusUpdate();
        status = PoolStatus.ACTIVE;
        emit PoolStatusUpdated(_msgSender(), PoolStatus.PENDING, PoolStatus.ACTIVE);
    }

    /// @notice This function is used to update the status of the pool to close
    /// @dev Only the admin can call this function
    function closePool() external onlyRole(ROLE_MANAGER) {
        if(status == PoolStatus.CLOSE) revert InvalidStatusUpdate();
        if(totalAssets() != 0)  revert WithdrawalPending();
        emit PoolStatusUpdated(_msgSender(), status, PoolStatus.CLOSE);
        status = PoolStatus.CLOSE;
    }

    /// @notice This function is used to update the AUM of the pool
    /// @dev Only the oracle manager can call this function
    /// @param _assetUnderManagement The new AUM
    function updateAssetUnderManagement(uint256 _assetUnderManagement) external onlyRole(ROLE_ORACLE_MANAGER) {
        if(status != PoolStatus.ACTIVE) revert PoolIsNotActive();
        if (msg.sender != fundManager) {
            if(assetUnderManagement > _assetUnderManagement) revert ("Threshold not met");
            uint64 currentSecond = uint64(block.timestamp % 86400);
            if (
                    currentSecond < pauseStartTime || 
                    currentSecond > pauseStartTime + pauseDuration
            )  {
                if(!paused()) revert("Pausable: not paused");
            }
            if (block.timestamp - AUMLastUpdatedAt < AUMUpdateCooldownPeriod) revert("Cooldown period not elapsed");
            if (assetUnderManagement * AUMChangeThresholdPercentage / 10000 < _assetUnderManagement) revert ("Threshold not met");
            AUMLastUpdatedAt = uint64(block.timestamp);
        }
        emit AssetUnderManagementUpdated(_msgSender(), assetUnderManagement, _assetUnderManagement);
        assetUnderManagement = _assetUnderManagement;
    }

    /// This function is used to update the pause duration
    /// @dev Only the admin can call this function
    /// @param _duration The new pause duration
    function updatePauseDuration(uint64 _duration) external onlyRole(ROLE_MANAGER) {
        pauseDuration = _duration;
    }

    /// @notice This function is used to update the pause start time
    /// @dev Only the admin can call this function
    /// @param _time The new pause start time
    function updatePauseStartTime(uint64 _time) external onlyRole(ROLE_MANAGER) {
        pauseStartTime = _time;
    }

    /// @notice This function is used to update the reserve percentage
    /// @dev Only the admin or pool manager can call this function
    /// @param _percentage The new reserve percentage
    function updateNonReservePercentage(uint64 _percentage) external onlyRole(ROLE_MANAGER) {
        nonReservePercentage = _percentage;
    }

    /// @notice This function is used to update the AUM update cooldown period
    /// @dev Only the admin can call this function
    /// @param _cooldownPeriod The new cooldown period
    function updateAUMUpdateCooldownPeriod(uint64 _cooldownPeriod) external onlyRole(ROLE_MANAGER) {
        AUMUpdateCooldownPeriod = _cooldownPeriod;
    }

    /// @notice This function is used to update the AUM change threshold percentage
    /// @dev Only the admin can call this function
    /// @param _thresholdPercentage The new threshold percentage
    function updateAUMChangeThresholdPercentage(uint64 _thresholdPercentage) external onlyRole(ROLE_MANAGER) {
        AUMChangeThresholdPercentage = 10000 + _thresholdPercentage;
    }

    /// @notice Creates a new withdrawal manager
    /// @param _csigmaRouter The address of the cSigma router
    /// @return _withdrawalManager The address of the withdrawal manager
    function createWithdrawalManager(address _csigmaRouter) external onlyRole(ROLE_MANAGER) returns (address _withdrawalManager) {
        _withdrawalManager = address(new ERC1967Proxy(withdrawalManagerImplementation, abi.encodeWithSelector(CsigmaV3WithdrawalManager.initialize.selector, asset(), address(this), _csigmaRouter)));
        withdrawalManager = _withdrawalManager;
        emit WithdrawalManagerCreated(_withdrawalManager, address(this));
    }

    /// @notice Updates the implementation of a withdrawalManager proxy
    /// @param _newImplementation The address of the new implementation
    function upgradeWithdrawalManager(address _newImplementation) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if(_newImplementation == address(0)) {
            revert InvalidAddress(_newImplementation);
        }
        withdrawalManagerImplementation = _newImplementation;
        UUPSUpgradeable(withdrawalManager).upgradeTo(_newImplementation);
    }

    /// @notice Updates the withdrawal manager implementation address
    /// @param _newImplementation The address of the new withdrawal manager implementation
    function updateWithdrawalManagerImplementation(address _newImplementation) external onlyRole(ROLE_MANAGER) {
        if(_newImplementation == address(0)) {
            revert InvalidAddress(_newImplementation);
        }
        withdrawalManagerImplementation = _newImplementation;
    }

    /// @notice This function is used to check if the account is an oracle manager
    /// @param _account The address of the account
    function isOracleManager(address _account) public view returns (bool) {
        return hasRole(ROLE_ORACLE_MANAGER, _account);
    }

    /// @notice Pauses the contract 
    /// @dev Only the admin can call this function
    function pause() external {
        require(
            hasRole(ROLE_MANAGER, _msgSender()) || 
            hasRole(ROLE_ORACLE_MANAGER, _msgSender()), 
            "Access Denied"
        );
        _pause();
    }

    /// @notice Unpauses the contract
    /// @dev Only the admin can call this function
    function unpause() external {
        require(
            hasRole(ROLE_MANAGER, _msgSender()) || 
            hasRole(ROLE_ORACLE_MANAGER, _msgSender()), 
            "Access Denied"
        );
        _unpause();
    }

    /// @notice Adds an oracle manager
    /// @dev Only the admin can call this function
    /// @param _account The address of the oracle manager
    function addOracleManager(address _account) public onlyRole(DEFAULT_ADMIN_ROLE) {
        grantRole(ROLE_ORACLE_MANAGER, _account);
        emit OracleManagerAdded(_account);
    }

    /// @notice Removes an oracle manager
    /// @dev Only the admin can call this function
    /// @param _account The address of the oracle manager
    function removeOracleManager(address _account) public onlyRole(DEFAULT_ADMIN_ROLE) {
        revokeRole(ROLE_ORACLE_MANAGER, _account);
        emit OracleManagerRemoved(_account);
    }

    /// @notice This function is used to send funds from reserve to fund manager
    /// @dev Only the pool manager can call this function
    /// @param _amount The amount to send 
    function sendReserveToFundManager(uint256 _amount) external {
        if(_msgSender() != poolManager) revert AccessDenied(_msgSender());
        SafeERC20Upgradeable.safeTransfer(IERC20Upgradeable(poolToken), fundManager, _amount);
        emit SendReserveToFundManager(fundManager, _amount);
    }

    /// @notice Withdraws the funds from the contract
    /// @dev Only the admin can call this function
    /// @param _token The address of the token
    /// @param _to The address to which the funds are withdrawn
    /// @param _amount The amount to withdraw
    function emergencyWithdraw(address _token, address _to, uint256 _amount) external onlyRole(DEFAULT_ADMIN_ROLE) {
        SafeERC20Upgradeable.safeTransfer(IERC20Upgradeable(_token), _to, _amount);
        emit EmergencyWithdraw(_token, _to, _amount);
    }

    /// @notice Updates the AUM of the pool
    /// @param _assetUnderManagement The new AUM
    function emergencyUpdateAUM(uint256 _assetUnderManagement) external onlyRole(DEFAULT_ADMIN_ROLE) {
        emit AssetUnderManagementUpdated(_msgSender(), assetUnderManagement, _assetUnderManagement);
        assetUnderManagement = _assetUnderManagement;
    }

    /// @notice Transfers the admin role to a new address
    /// @param _newOwner The address of the new admin
    function transferAdmin(address _newOwner) public {
        grantRole(DEFAULT_ADMIN_ROLE, _newOwner);
        revokeRole(DEFAULT_ADMIN_ROLE, _msgSender());
        emit AdminTransferred(_msgSender(), _newOwner);
    }    

    /// @notice Grants the given role to the account
    /// @param role The role to grant
    /// @param _account The address to which the role is granted
    function grantRole(bytes32 role, address _account)
        public
        virtual
        override
        onlyRole(getRoleAdmin(role))
        whenNotPaused
    {
        _grantRole(role, _account);
    }

    /// @notice Revokes the given role from the account
    /// @param role The role to revoke
    /// @param _account The address from which the role is revoked
    function revokeRole(bytes32 role, address _account)
        public
        override
        onlyRole(getRoleAdmin(role))        
        whenNotPaused
    {
        _revokeRole(role, _account);
    }

    /// @notice Upgrades the contract to a new implementation
    /// @dev Only the admin can call this function
    /// @param _newImplementation The address of the new implementation
    function _authorizeUpgrade(address _newImplementation)
        internal
        override
        onlyRole(DEFAULT_ADMIN_ROLE)
    {}

    /// @notice Checks if current time is within the default pause window
    /// @dev Reverts if within pause window based on daily timing
    function _requireNotInDefaultPauseWindow() internal view {
        uint64 currentSecond = uint64(block.timestamp % 86400);
        require(
            currentSecond < pauseStartTime || 
            currentSecond > pauseStartTime + pauseDuration,
            "Pausable: paused"
        );
    }

    /// @notice Internal withdraw function with withdrawal manager integration
    /// @dev Checks for pending withdrawals before allowing direct withdrawals
    /// @param caller The address initiating the withdrawal
    /// @param receiver The address receiving the assets
    /// @param owner The owner of the shares being redeemed
    /// @param assets The amount of assets being withdrawn
    /// @param shares The amount of shares being burned
    function _withdraw(
        address caller,
        address receiver,
        address owner,
        uint256 assets,
        uint256 shares
    ) internal virtual override {
        if (caller != withdrawalManager)
            if (withdrawalManager != address(0))
                require(WithdrawManager(withdrawalManager).totalDueLPToken() == 0, "Withdrawal pending");
        super._withdraw(caller, receiver, owner, assets, shares);
    }

    /// @notice Returns the allowance of spender for owner's tokens
    /// @dev Delegates to the share token contract
    /// @param owner The token owner address
    /// @param spender The address authorized to spend
    /// @return The current allowance amount
    function allowance(address owner, address spender) external view returns (uint256) {
        return IERC20MetadataUpgradeable(share).allowance(owner, spender);
    }
    
    /// @notice Approves spender to spend amount of caller's tokens
    /// @dev Delegates to the share token contract
    /// @param spender The address to approve
    /// @param amount The amount to approve
    /// @return bool True if approval was successful
    function approve(address spender, uint256 amount) external returns (bool) {
        return IShareToken(share).nativeApprove(_msgSender(), spender, amount);
    }
    
    /// @notice Transfers amount of tokens to recipient
    /// @dev Delegates to the share token contract
    /// @param to The recipient address
    /// @param amount The amount to transfer
    /// @return bool True if transfer was successful
    function transfer(address to, uint256 amount) external returns (bool) {
        return IShareToken(share).nativeTransfer(_msgSender(), to, amount);
    }
    
    /// @notice Transfers amount of tokens from one address to another
    /// @dev Delegates to the share token contract
    /// @param from The sender address
    /// @param to The recipient address
    /// @param amount The amount to transfer
    /// @return bool True if transfer was successful
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        return IShareToken(share).nativeTransferFrom(_msgSender(), from, to, amount);
    }
    
    /// @notice Returns the token balance of an account
    /// @dev Delegates to the share token contract
    /// @param account The account to query
    /// @return The token balance
    function balanceOf(address account) external view returns (uint256) {
        return IERC20MetadataUpgradeable(share).balanceOf(account);
    }
    
    /// @notice Returns the name of the token
    /// @dev Delegates to the share token contract
    /// @return The token name
    function name() external view returns (string memory) {
        return IERC20MetadataUpgradeable(share).name();
    }
    
    /// @notice Returns the symbol of the token
    /// @dev Delegates to the share token contract
    /// @return The token symbol
    function symbol() external view returns (string memory) {
        return IERC20MetadataUpgradeable(share).symbol();
    }
    
    /// @notice Returns the total supply of tokens
    /// @dev Delegates to the share token contract
    /// @return The total token supply
    function totalSupply() external view returns (uint256) {
        return IERC20MetadataUpgradeable(share).totalSupply();
    }
}

contracts/v3/CsigmaUSD.sol.content:
// SPDX-License-Identifier: BUSL-1.1
// @author cSigma Finance Inc., a Delaware company, for its Real World Credit tokenization protocol

pragma solidity 0.8.26;

import "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC20/extensions/draft-ERC20PermitUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/PausableUpgradeable.sol";

error AccessDenied(address _executor);

/// @title SanctionList
/// @notice This interface is used to check if the user is sanctioned
interface SanctionsList {
    function isSanctioned(address addr) external view returns (bool);
}

/// @title CsigmaUSD
/// @notice A yield bearing token contract with role-based access control, sanctions compliance, and pausability
/// @dev This contract implements an upgradeable ERC20 token with additional features:
//      - Role-based access control (Controller, Manager, Admin roles)
//      - Sanctions compliance through Chainalysis integration
//      - Pausability for emergency situations
//      - EIP-2612 permit functionality
//      - Vault management for underlying assets
/// @author cSigma Finance Inc.
contract CsigmaUSD is
    Initializable,
    ERC20Upgradeable,
    AccessControlUpgradeable,
    ERC20PermitUpgradeable,
    UUPSUpgradeable,
    PausableUpgradeable
{
    /// @notice Role that can mint and burn tokens
    bytes32 public constant CONTROLLER_ROLE = keccak256("CONTROLLER_ROLE");
    
    /// @notice Role that can manage administrative functions
    bytes32 public constant MANAGER_ROLE = keccak256("MANAGER_ROLE");

    /// @notice Mapping of underlying asset addresses to their associated vault addresses
    mapping (address => address) public vault;
    
    /// @notice Address of the Chainalysis sanctions list contract
    address public chainalysis;

    /// @notice Emitted when a new controller is added
    /// @param _account Address of the new controller
    event ControllerAdded(address _account);
    
    /// @notice Emitted when a controller is removed
    /// @param _account Address of the removed controller
    event ControllerRemoved(address _account);
    
    /// @notice Emitted when a new manager is added
    /// @param _account Address of the new manager
    event ManagerAdded(address _account);
    
    /// @notice Emitted when a manager is removed
    /// @param _account Address of the removed manager
    event ManagerRemoved(address _account);
    
    /// @notice Emitted when admin role is transferred
    /// @param _oldOwner Address of the previous admin
    /// @param _newOwner Address of the new admin
    event AdminTransferred(address _oldOwner, address _newOwner);
    
    /// @notice Emitted when a vault address is updated for an asset
    /// @param _asset Address of the underlying asset
    /// @param _vault Address of the associated vault
    event UpdateVault(address _asset, address _vault);

    /// @notice Ensures the provided address is not the zero address
    /// @param _account The address to validate
    modifier notZeroAddress(address _account) {
        require(_account != address(0), "address cannot be zero");
        _;
    }

    /// @notice Ensures the user is not on the sanctions list
    /// @param _user The address to check against the sanctions list
    modifier whenNotSanctioned(address _user) {
        if(SanctionsList(chainalysis).isSanctioned(_user)) {
            revert AccessDenied(_user);
        }
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @notice Initializes the contract with the given parameters
    /// @dev This function replaces the constructor for upgradeable contracts
    /// @param _name Name of the token
    /// @param _symbol Symbol of the token
    /// @param _controller Address to be granted the CONTROLLER_ROLE
    /// @param _manager Address to be granted the MANAGER_ROLE
    /// @param _chainalysis Address of the Chainalysis sanctions list contract
    function initialize(
        string calldata _name,
        string calldata _symbol,
        address _controller,
        address _manager,
        address _chainalysis
    )
        public
        initializer
        notZeroAddress(_controller)
        notZeroAddress(_manager)
    {
        // Initializes underlying contracts
        __ERC20_init(_name, _symbol);
        __AccessControl_init();
        __ERC20Permit_init(_name);
        __UUPSUpgradeable_init();
        __Pausable_init();

        // Grants roles to given addresses
        _grantRole(DEFAULT_ADMIN_ROLE, _msgSender());
        _grantRole(CONTROLLER_ROLE, _controller);
        _grantRole(MANAGER_ROLE, _manager);

        // Records chainalysis address
        chainalysis = _chainalysis;
    }

    /// @notice Returns true if the contract supports a given interface
    /// @param interfaceId Interface identifier (ERC-165, ERC-7575, IERC20)
    /// @return bool True if the interface is supported
    function supportsInterface(bytes4 interfaceId) public view virtual override returns (bool) {
        return
        interfaceId == 0xf815c03d ||
        interfaceId == type(ERC165Upgradeable).interfaceId ||
        interfaceId == type(IERC20Upgradeable).interfaceId;
	}

    /// @notice Mints new tokens to a specified address
    /// @dev Only callable by addresses with CONTROLLER_ROLE
    /// @param _to Address to mint tokens to
    /// @param _amount Amount of tokens to mint
    function mint(address _to, uint256 _amount) external onlyRole(CONTROLLER_ROLE) {
        require(_amount > 0, "amount must be greater than 0");
        _mint(_to, _amount);
    }

    /// @notice Burns tokens from a specified address
    /// @dev Only callable by addresses with CONTROLLER_ROLE
    /// @param _from Address to burn tokens from
    /// @param _amount Amount of tokens to burn
    function burn(address _from, uint256 _amount) external onlyRole(CONTROLLER_ROLE) {
        require(_amount > 0, "amount must be greater than 0");
        _burn(_from, _amount);
    }

    /// @notice Spends allowance on behalf of an owner
    /// @dev Only callable by addresses with CONTROLLER_ROLE when not paused
    /// @param owner Address of the token owner
    /// @param caller Address spending the allowance
    /// @param shares Amount of allowance to spend
    function spendAllowance(address owner, address caller, uint256 shares) external whenNotPaused onlyRole(CONTROLLER_ROLE) {
        _spendAllowance(owner, caller, shares);
    }

    /// @notice Sets approval for a spender on behalf of an owner
    /// @dev Only callable by addresses with CONTROLLER_ROLE when not paused
    /// @param owner Address of the token owner
    /// @param spender Address to approve
    /// @param amount Amount to approve
    /// @return bool True if successful
    function nativeApprove(address owner, address spender, uint256 amount) external whenNotPaused onlyRole(CONTROLLER_ROLE) returns(bool) {
        _approve(owner, spender, amount);
        return true;
    }

    /// @notice Transfers tokens on behalf of an owner
    /// @dev Only callable by addresses with CONTROLLER_ROLE
    /// @param owner Address of the token owner
    /// @param to Address to transfer tokens to
    /// @param amount Amount of tokens to transfer
    /// @return bool True if successful
    function nativeTransfer(address owner, address to, uint256 amount) external onlyRole(CONTROLLER_ROLE) returns (bool) {
        _transfer(owner, to, amount);
        return true;
    }

    /// @notice Transfers tokens from one address to another using allowance
    /// @dev Only callable by addresses with CONTROLLER_ROLE
    /// @param spender Address spending the allowance
    /// @param from Address to transfer tokens from
    /// @param to Address to transfer tokens to
    /// @param amount Amount of tokens to transfer
    /// @return bool True if successful
    function nativeTransferFrom(address spender, address from, address to, uint256 amount) external onlyRole(CONTROLLER_ROLE) returns (bool) {
        _spendAllowance(from, spender, amount);
        _transfer(from, to, amount);
        return true;
    }

    /// @notice Approves a spender to use tokens on behalf of the caller
    /// @dev Overrides the standard approve function to include pause and sanctions checks
    /// @param _spender Address to approve
    /// @param _value Amount to approve
    /// @return bool True if successful
    function approve(address _spender, uint256 _value)
        public
        override
        whenNotPaused
        whenNotSanctioned(_spender)
        returns (bool)
    {
        return super.approve(_spender, _value);
    }

    /// @notice Returns the number of decimals used by the token
    /// @dev Overrides the default 18 decimals to use 6 decimals
    /// @return uint8 The number of decimals (6)
    function decimals() public pure override returns (uint8) {
        return 6;
    }

    /// @notice Hook that is called before any token transfer
    /// @dev Includes pause and sanctions checks for both sender and receiver
    /// @param _from Address tokens are being transferred from
    /// @param _to Address tokens are being transferred to
    /// @param _amount Amount of tokens being transferred
    function _beforeTokenTransfer(
        address _from,
        address _to,
        uint256 _amount
    )
        internal
        override
        whenNotPaused
        whenNotSanctioned(_from)
        whenNotSanctioned(_to)
    {
        super._beforeTokenTransfer(_from, _to, _amount);
    }

    /// @notice Increases the allowance granted to a spender
    /// @dev Overrides the standard function to include pause and sanctions checks
    /// @param _spender Address to increase allowance for
    /// @param _increment Amount to increase allowance by
    /// @return bool True if successful
    function increaseAllowance(address _spender, uint256 _increment)
        public
        override
        whenNotPaused
        whenNotSanctioned(_spender)
        returns (bool)
    {
        return super.increaseAllowance(_spender, _increment);
    }

    /// @notice Decreases the allowance granted to a spender
    /// @dev Overrides the standard function to include pause and sanctions checks
    /// @param _spender Address to decrease allowance for
    /// @param _decrement Amount to decrease allowance by
    /// @return bool True if successful
    function decreaseAllowance(address _spender, uint256 _decrement)
        public
        override
        whenNotPaused
        whenNotSanctioned(_spender)
        returns (bool)
    {
        return super.decreaseAllowance(_spender, _decrement);
    }

    /// @notice Allows approval via signature (EIP-2612)
    /// @dev Overrides the standard permit function to include pause and sanctions checks
    /// @param _owner Address of the token owner
    /// @param _spender Address to approve
    /// @param _value Amount to approve
    /// @param _deadline Expiration time of the permit
    /// @param _v Recovery parameter of the signature
    /// @param _r First 32 bytes of the signature
    /// @param _s Second 32 bytes of the signature
    function permit(
        address _owner,
        address _spender,
        uint256 _value,
        uint256 _deadline,
        uint8 _v,
        bytes32 _r,
        bytes32 _s
    )
        public
        override
        whenNotPaused
        whenNotSanctioned(_spender)
    {
        super.permit(_owner, _spender, _value, _deadline, _v, _r, _s);
    }

    /// @notice Checks if an address has the CONTROLLER_ROLE
    /// @param _account Address to check
    /// @return bool True if the address has the CONTROLLER_ROLE
    function isController(address _account) public view returns (bool) {
        return hasRole(CONTROLLER_ROLE, _account);
    }

    /// @notice Checks if an address has the MANAGER_ROLE
    /// @param _account Address to check
    /// @return bool True if the address has the MANAGER_ROLE
    function isManager(address _account) public view returns (bool) {
        return hasRole(MANAGER_ROLE, _account);
    }

    /// @notice Pauses all token operations
    /// @dev Only callable by addresses with MANAGER_ROLE
    function pause() external onlyRole(MANAGER_ROLE) {
        _pause();
    }

    /// @notice Unpauses all token operations
    /// @dev Only callable by addresses with MANAGER_ROLE
    function unpause() external onlyRole(MANAGER_ROLE) {
        _unpause();
    }

    /// @notice Updates the vault address associated with an underlying asset
    /// @param _asset Address of the underlying asset
    /// @param _vault Address of the associated vault
    function updateVault(address _asset, address _vault) public onlyRole(MANAGER_ROLE) {
        vault[_asset] = _vault;
        emit UpdateVault(_asset, _vault);
    }

    /// @notice Adds a new controller to the system
    /// @dev Grants CONTROLLER_ROLE to the specified account
    /// @param _account Address to grant controller role to
    function addController(address _account) public           
    {
        grantRole(CONTROLLER_ROLE, _account);
        emit ControllerAdded(_account);
    }

    /// @notice Removes a controller from the system
    /// @dev Revokes CONTROLLER_ROLE from the specified account
    /// @param _account Address to revoke controller role from
    function removeController(address _account) public {
        revokeRole(CONTROLLER_ROLE, _account);
        emit ControllerRemoved(_account);
    }

    /// @notice Adds a new manager to the system
    /// @dev Grants MANAGER_ROLE to the specified account
    /// @param _account Address to grant manager role to
    function addManager(address _account) public         
    {
        grantRole(MANAGER_ROLE, _account);
        emit ManagerAdded(_account);
    }

    /// @notice Removes a manager from the system
    /// @dev Revokes MANAGER_ROLE from the specified account
    /// @param _account Address to revoke manager role from
    function removeManager(address _account) public        
    {
        revokeRole(MANAGER_ROLE, _account);
        emit ManagerRemoved(_account);
    }

    /// @notice Transfers admin role to a new address
    /// @dev Grants DEFAULT_ADMIN_ROLE to new owner and revokes it from current admin
    /// @param _newOwner Address of the new admin
    function transferAdmin(address _newOwner) public
    {
        grantRole(DEFAULT_ADMIN_ROLE, _newOwner);
        revokeRole(DEFAULT_ADMIN_ROLE, _msgSender());
        emit AdminTransferred(_msgSender(), _newOwner);
    }    

    /// @notice Grants a role to an account
    /// @dev Overrides the standard function to include additional checks
    /// @param role The role to grant
    /// @param _account Address to grant the role to
    function grantRole(bytes32 role, address _account)
        public
        virtual
        override
        onlyRole(getRoleAdmin(role))
        notZeroAddress(_account)
        whenNotPaused
    {
        _grantRole(role, _account);
    }

    /// @notice Revokes a role from an account
    /// @dev Overrides the standard function to include additional checks
    /// @param role The role to revoke
    /// @param _account Address to revoke the role from
    function revokeRole(bytes32 role, address _account)
        public
        override
        onlyRole(getRoleAdmin(role))        
        notZeroAddress(_account)        
        whenNotPaused
    {
        _revokeRole(role, _account);
    }

    /// @notice Authorizes contract upgrades
    /// @dev Only callable by addresses with DEFAULT_ADMIN_ROLE (admin)
    /// @param _newImplementation Address of the new implementation contract
    function _authorizeUpgrade(address _newImplementation)
        internal
        override
        onlyRole(DEFAULT_ADMIN_ROLE)
    {}
}

contracts/v3/CsigmaV3WithdrawalManager.s.content:
// SPDX-License-Identifier: BUSL-1.1
// @author cSigma Finance Inc., a Delaware company, for its Real World Credit tokenization protocol

pragma solidity 0.8.26;

import "@openzeppelin/contracts-upgradeable/token/ERC20/utils/SafeERC20Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/interfaces/IERC20Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import "@openzeppelin/contracts/interfaces/IERC4626.sol";
import "./CsigmaERC7575Vault.sol";

/// @title ICsigmaPool
/// @notice Interface for CsigmaV3Pool contract
interface ICsigmaPool{
    function fundManager() external view returns (address);
    function poolManager() external view returns (address);
    function share() external view returns (address);
}

/// @title CsigmaV3WithdrawalManager
/// @notice Manages fund withdrawals using a queue-based system for the cSigma protocol
/// @dev This contract handles withdrawal requests, repayments, and claims in a FIFO queue system
/// @dev Supports partial fulfillment of withdrawal requests based on available reserves
/// @author cSigma Finance Inc.
contract CsigmaV3WithdrawalManager is
    Initializable,
    AccessControlUpgradeable,
    UUPSUpgradeable,
    PausableUpgradeable
{
    /// @notice Role identifier for managers who can execute repayments
    bytes32 public constant MANAGER_ROLE = keccak256("MANAGER_ROLE");

    /// @notice Represents a withdrawal request in the queue
    /// @param pendingShareTokenAmount Amount of share tokens still pending withdrawal
    /// @param cumulativeShareTokenAmount Total cumulative share tokens up to this position
    /// @param fulfilledAmount Amount of underlying tokens already fulfilled for this request
    /// @param owner Address that owns this withdrawal request
    /// @param isRepaymentCheckPoint Whether this position serves as a repayment checkpoint
    struct WithdrawalRequest {
        uint256 pendingShareTokenAmount;
        uint256 cumulativeShareTokenAmount;
        uint256 fulfilledAmount;
        address owner;
        bool isRepaymentCheckPoint;
    }

    /// @notice Represents repayment data for calculating exchange ratios
    /// @param queuePosition Queue position where this repayment was made
    /// @param exchangeRatio Exchange ratio between share tokens and underlying tokens at repayment time
    struct RepaymentData {
        uint256 queuePosition;
        uint256 exchangeRatio;
    }

    /// @notice The underlying token used for withdrawals (e.g., USDC, USDT) 
    IERC20Upgradeable  public underlyingToken;
    
    /// @notice The cSigma V3 Pool contract instance
    CsigmaV3Pool public csigmaV3Pool;

    /// @notice Current position in the withdrawal queue (last assigned position)
    uint256 public currentQueuePosition;
    
    /// @notice Last fulfilled position in the withdrawal queue
    uint256 public fulfilledQueuePosition;
    
    /// @notice Total amount of share tokens currently due for withdrawal
    uint256 public totalDueShareToken;

    /// @notice Array storing repayment data for exchange ratio calculations
    RepaymentData[] public repaymentData;
    
    /// @notice Mapping from queue position to withdrawal request details
    mapping (uint256 => WithdrawalRequest) public withdrawalQueue;
    
    /// @notice Mapping from user address to their queue positions
    mapping (address => uint256[]) public withdrawalQueuePositions;

    /// @notice Address of the share token contract (csUSD)
    address public shareToken;
    
    /// @notice Address of the cSigma router contract
    address public csigmaRouter;

    /// @notice Emitted when a new withdrawal request is created
    /// @param queuePosition Position assigned to the request in the queue
    /// @param owner Address of the request owner
    /// @param shares Amount of share tokens requested for withdrawal
    event WithdrawRequest(uint256 indexed queuePosition, address indexed owner, uint256 shares);
    
    /// @notice Emitted when a withdrawal request is claimed
    /// @param queuePosition Position of the request in the queue
    /// @param owner Address of the request owner
    /// @param amount Amount of underlying tokens claimed
    event Claim(uint256 indexed queuePosition, address indexed owner, uint256 amount);
    
    /// @notice Emitted when a repayment is processed
    /// @param queuePosition Position up to which the repayment was processed
    /// @param repaymentShares Amount of share tokens used for repayment
    /// @param exchangeRatio Exchange ratio used for the repayment
    /// @param queuePositionFulfilledAmount Amount fulfilled at the specific queue position
    event Repayment(uint256 indexed queuePosition, uint256 repaymentShares, uint256 exchangeRatio, uint256 queuePositionFulfilledAmount);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @notice Initializes the withdrawal manager contract
    /// @dev Sets up access control, assigns manager roles, and initializes state variables
    /// @param _underlyingToken Address of the underlying token (e.g., USDC)
    /// @param _csigmaV3Pool Address of the cSigma V3 Pool contract
    /// @param _csigmaRouter Address of the cSigma router contract
    function initialize(address _underlyingToken, address _csigmaV3Pool, address _csigmaRouter) public initializer {
        __AccessControl_init();
        __UUPSUpgradeable_init();
        __Pausable_init();
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(MANAGER_ROLE, ICsigmaPool(_csigmaV3Pool).fundManager());
        _grantRole(MANAGER_ROLE, ICsigmaPool(_csigmaV3Pool).poolManager());
        underlyingToken = IERC20Upgradeable(_underlyingToken);
        csigmaV3Pool = CsigmaV3Pool(_csigmaV3Pool);
        shareToken = ICsigmaPool(_csigmaV3Pool).share();
        csigmaRouter = _csigmaRouter;
        repaymentData.push(RepaymentData(0, 0));
    }

    /// @notice Creates a withdrawal request for the user by entering the queue
    /// @dev If there are enough reserves, the user will receive (partially or completely) the underlying tokens immediately
    /// @param _shareTokenAmount The amount of share tokens to withdraw
    /// @param _owner The address of the user who owns the request
    /// @param _receiver The address of the receiver of the underlying tokens
    /// @return amountReceived The amount of underlying tokens received
    function requestWithdrawal(
        uint256 _shareTokenAmount, 
        address _owner, 
        address _receiver
    ) 
        external 
        returns (uint256 amountReceived) 
    {
        if (_shareTokenAmount == 0) {
            revert ("shareToken amount is zero");
        }
        csigmaV3Pool.transferFrom(msg.sender, address(this), _shareTokenAmount);
        uint256 reserve = csigmaV3Pool.maxRedeem(address(0));
        if (totalDueShareToken + _shareTokenAmount < reserve) {
            amountReceived = csigmaV3Pool.redeem(_shareTokenAmount, _receiver, address(this));
            emit Claim(0, _owner, amountReceived);
            return amountReceived;
        } else if(totalDueShareToken < reserve) {
            uint256 redeemAmount = (reserve - totalDueShareToken);
            amountReceived = csigmaV3Pool.redeem(redeemAmount, _receiver, address(this));
            emit Claim(0, _owner, amountReceived);
            _shareTokenAmount -= redeemAmount;
        } 
        totalDueShareToken += _shareTokenAmount;
        if (currentQueuePosition == 0) {
            withdrawalQueue[++currentQueuePosition] = WithdrawalRequest(_shareTokenAmount, _shareTokenAmount, 0, _owner, false);
            withdrawalQueuePositions[_owner].push(1);
            emit WithdrawRequest(1, _owner, _shareTokenAmount);
        }
        else {
            ++currentQueuePosition;
            withdrawalQueue[currentQueuePosition] = WithdrawalRequest(_shareTokenAmount, withdrawalQueue[currentQueuePosition - 1].cumulativeShareTokenAmount + _shareTokenAmount, 0, _owner, false);
            withdrawalQueuePositions[_owner].push(currentQueuePosition);
            emit WithdrawRequest(currentQueuePosition, _owner, _shareTokenAmount);
        }
        return amountReceived;
    }

    /// @notice Claims the underlying tokens for the user
    /// @dev The user can claim the underlying tokens only if the request is fulfilled
    /// @param queuePosition The position in the queue of the request
    /// @param repaymentDataIndex The index of the repayment data
    /// @return owner The address of the user who owns the request
    /// @return claimedAmount The amount of underlying tokens claimed
    function claim(uint256 queuePosition, uint256 repaymentDataIndex) external returns (address owner, uint256 claimedAmount) {
        WithdrawalRequest memory request = withdrawalQueue[queuePosition];
        address receiver = csigmaRouter;
        if (msg.sender != csigmaRouter) {
            receiver = msg.sender;
            if (msg.sender != request.owner) 
                revert ("Request is not owned by the caller");
        }
        if (queuePosition > fulfilledQueuePosition) {
            revert ("Queue position is not fulfilled yet");
        }
        if (request.isRepaymentCheckPoint) {
            if(request.fulfilledAmount == 0) {
                revert ("Request has been claimed");
            }
            SafeERC20Upgradeable.safeTransfer(underlyingToken, receiver, request.fulfilledAmount);
            emit Claim(queuePosition, request.owner, request.fulfilledAmount);
            withdrawalQueue[queuePosition].fulfilledAmount = 0;
            owner = request.owner;
            claimedAmount = request.fulfilledAmount;
        } else {
            RepaymentData memory lowerData = repaymentData[repaymentDataIndex - 1];
            RepaymentData memory currentData = repaymentData[repaymentDataIndex];
            if (lowerData.queuePosition >= queuePosition || currentData.queuePosition < queuePosition) {
                revert ("Repayment data index is not valid");
            }
            uint256 exchangeRatio = currentData.exchangeRatio;
            claimedAmount = request.pendingShareTokenAmount * exchangeRatio / 10 ** IERC20Metadata(shareToken).decimals();
            withdrawalQueue[queuePosition].pendingShareTokenAmount = 0;
            if(claimedAmount == 0) {
                revert ("Request has been claimed");
            }
            emit Claim(queuePosition, receiver, claimedAmount);
            SafeERC20Upgradeable.safeTransfer(underlyingToken, receiver, claimedAmount);
            owner = request.owner;
        }
    }

    /// @notice Repays the fund using Share tokens
    /// @dev The repayment is done using a queue system, where the user can specify the position in the queue to repay up to
    /// @param uptoQueuePosition The position in the queue to repay up to
    /// @param amount The amount of Share tokens to repay
    function repay(uint256 uptoQueuePosition, uint256 amount) external onlyRole(MANAGER_ROLE) {
        if (fulfilledQueuePosition > uptoQueuePosition) {
            revert ("Queue position is not valid");
        }

        if (totalDueShareToken == 0) {
            return;
        }
        
        if (uptoQueuePosition > currentQueuePosition) {
            uptoQueuePosition = currentQueuePosition;
        }

        uint256 paymentShareTokenAmount = csigmaV3Pool.previewWithdraw(amount);
        if (paymentShareTokenAmount > totalDueShareToken) {
            paymentShareTokenAmount = totalDueShareToken;
        }
        uint256 amountReceived = csigmaV3Pool.previewRedeem(paymentShareTokenAmount);
        uint256 maxWithdraw = csigmaV3Pool.maxWithdraw(address(0));
        if (maxWithdraw <= amountReceived) {
            paymentShareTokenAmount = csigmaV3Pool.withdraw(maxWithdraw, address(this), address(this));
            amountReceived = maxWithdraw;
        } else {
            csigmaV3Pool.redeem(paymentShareTokenAmount, address(this), address(this));
        }
        uint256 multiplier = 10 ** IERC20Metadata(shareToken).decimals();
        uint256 exchangeRatio = (amountReceived * multiplier) / paymentShareTokenAmount;

        uint256 fulfilledShareToken;

        if (fulfilledQueuePosition < uptoQueuePosition) {

            uint256 dueShareToken = withdrawalQueue[uptoQueuePosition].cumulativeShareTokenAmount 
                                + withdrawalQueue[fulfilledQueuePosition].pendingShareTokenAmount
                                - withdrawalQueue[fulfilledQueuePosition].cumulativeShareTokenAmount;
  
            if (
                paymentShareTokenAmount 
                    <= withdrawalQueue[uptoQueuePosition - 1].cumulativeShareTokenAmount 
                        + withdrawalQueue[fulfilledQueuePosition].pendingShareTokenAmount
                        - withdrawalQueue[fulfilledQueuePosition].cumulativeShareTokenAmount 
            ) {
                revert ("Payment amount is not enough");
            }

            uint256 pendingShareTokenAmount = dueShareToken - paymentShareTokenAmount;
            fulfilledShareToken = withdrawalQueue[uptoQueuePosition].pendingShareTokenAmount - pendingShareTokenAmount;

            withdrawalQueue[uptoQueuePosition].pendingShareTokenAmount = pendingShareTokenAmount;
            withdrawalQueue[uptoQueuePosition].isRepaymentCheckPoint = true;
            withdrawalQueue[uptoQueuePosition].fulfilledAmount += (fulfilledShareToken * exchangeRatio) / multiplier;

            withdrawalQueue[fulfilledQueuePosition].fulfilledAmount += (withdrawalQueue[fulfilledQueuePosition].pendingShareTokenAmount * exchangeRatio) / multiplier;
            withdrawalQueue[fulfilledQueuePosition].pendingShareTokenAmount = 0;

            fulfilledQueuePosition = uptoQueuePosition;
            emit Repayment(uptoQueuePosition, paymentShareTokenAmount, exchangeRatio, (fulfilledShareToken * exchangeRatio) / multiplier);
            repaymentData.push(RepaymentData(uptoQueuePosition - 1, exchangeRatio));

        } else {
            uint256 dueShareToken = withdrawalQueue[uptoQueuePosition].pendingShareTokenAmount;
            uint256 pendingShareTokenAmount = dueShareToken - paymentShareTokenAmount;
            withdrawalQueue[uptoQueuePosition].pendingShareTokenAmount = pendingShareTokenAmount;
            withdrawalQueue[uptoQueuePosition].fulfilledAmount += (paymentShareTokenAmount * exchangeRatio) / multiplier;
            emit Repayment(uptoQueuePosition, paymentShareTokenAmount, exchangeRatio, (paymentShareTokenAmount * exchangeRatio) / multiplier);
        }
        totalDueShareToken -= paymentShareTokenAmount;
    }

    /// @notice Updates the csigmaRouter address
    /// @param _csigmaRouter The address of the new csigmaRouter
    function updateCsigmaRouter(address _csigmaRouter) external onlyRole(DEFAULT_ADMIN_ROLE) {
        csigmaRouter = _csigmaRouter;
    }

    /// @notice Upgrades the contract to a new implementation
    /// @dev Only the admin can call this function
    /// @param _newImplementation The address of the new implementation
    function _authorizeUpgrade(address _newImplementation)
        internal
        override
        onlyRole(DEFAULT_ADMIN_ROLE)
    {}

    /// @notice Returns the checkpoint of the repayment data
    function getRepaymentData() external view returns (RepaymentData[] memory) {
        return repaymentData;
    }

    /// @notice Returns total number of requests in the queue for given user
    /// @param user The address of the user
    /// @return The number of requests in the queue for the user
    function getUserRequestsCount(address user) external view returns (uint256) {
        return withdrawalQueuePositions[user].length;
    }

    /// @notice Extended withdrawal request data for external queries
    /// @param queuePosition Position of the request in the withdrawal queue
    /// @param pendingShareTokenAmount Amount of share tokens still pending
    /// @param cumulativeShareTokenAmount Cumulative share token amount up to this position
    /// @param fulfilledAmount Amount already fulfilled in underlying tokens
    /// @param owner Owner of the withdrawal request
    /// @param isRepaymentCheckPoint Whether this is a repayment checkpoint
    struct WithdrawalRequestData {
        uint256 queuePosition;
        uint256 pendingShareTokenAmount;
        uint256 cumulativeShareTokenAmount;
        uint256 fulfilledAmount;
        address owner;
        bool isRepaymentCheckPoint;
    }

    /// @notice Returns the requests in the queue for given user
    /// @param user The address of the user
    /// @return requests The array of requests in the queue for the user
    function getUserRequests(address user) external view returns (WithdrawalRequestData[] memory requests) {
        uint256[] memory positions = withdrawalQueuePositions[user];
        requests = new WithdrawalRequestData[](positions.length);
        for (uint256 i = 0; i < positions.length; i++) {
            requests[i] = WithdrawalRequestData(
                positions[i],
                withdrawalQueue[positions[i]].pendingShareTokenAmount,
                withdrawalQueue[positions[i]].cumulativeShareTokenAmount,
                withdrawalQueue[positions[i]].fulfilledAmount,
                withdrawalQueue[positions[i]].owner,
                withdrawalQueue[positions[i]].isRepaymentCheckPoint
            );
        }
    }

    /// @notice Returns the LP token address (alias for shareToken)
    /// @dev Provided for compatibility with external interfaces
    /// @return The address of the share/LP token
    function LPToken() external view returns (address) {
        return shareToken;
    }
}

contracts/v3/CSUSDFundManager.sol.content:
// SPDX-License-Identifier: BUSL-1.1
// @author cSigma Finance Inc., a Delaware company, for its Real World Credit tokenization protocol

pragma solidity 0.8.26;

import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC20/utils/SafeERC20Upgradeable.sol";
import { Commands } from "@uniswap/universal-router/contracts/libraries/Commands.sol";
import { IPoolManager } from "@uniswap/v4-core/src/interfaces/IPoolManager.sol";
import { IV4Router } from "@uniswap/v4-periphery/src/interfaces/IV4Router.sol";
import { Actions } from "@uniswap/v4-periphery/src/libraries/Actions.sol";
import { IPermit2 } from "@uniswap/permit2/src/interfaces/IPermit2.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { StateLibrary } from "@uniswap/v4-core/src/libraries/StateLibrary.sol";
import { PoolKey } from '@uniswap/v4-core/src/types/PoolKey.sol';
import { IUniversalRouter } from '@uniswap/universal-router/contracts/interfaces/IUniversalRouter.sol';
import "../interfaces/ICsigmaInst.sol";
import "./CsigmaERC7575Vault.sol";

error V1PoolIsNotActive(string _poolId);
error InvalidV1Pool(string _poolId);
error InvalidAllocation(uint256 _allocation, address _token);
error InvalidV1Amount(uint256 _v1Amount);
error InvalidAmount(uint256 _v2Amount, uint256 _v1Amount);
error DuplicatePool(string _poolId);

/// @title CSUSDFundManager
/// @notice This contract manages the fund deployment and claim process for the cSigma V3 Pool Managers
/// @dev Implements role-based access control, pausability, and UUPS upgradeable pattern
/// @dev Manages allocation of funds between V1 and V3 pools with automatic rebalancing
/// @author cSigma Finance Inc.
contract CSUSDFundManager is
    Initializable,
    AccessControlUpgradeable,
    UUPSUpgradeable,
    PausableUpgradeable
{
    using StateLibrary for IPoolManager;
    
    /// @notice Role identifier for managers who can perform administrative operations
    bytes32 public constant ROLE_MANAGER = keccak256("ROLE_MANAGER");
    
    /// @notice Address of the Uniswap V4 router for token swaps
    address public router;
    
    /// @notice Uniswap V4 pool manager interface
    IPoolManager public poolManager;
    
    /// @notice Permit2 contract for gasless token approvals
    IPermit2 public permit2;

    /// @notice Address of the V1 diamond contract
    address public diamondV1;
    
    /// @notice Unique identifier for this fund manager as a lender in V1
    string public fundManagerLenderId;
    
    /// @notice Maps token addresses to their corresponding V3 pool addresses
    mapping (address => address) public pool;
    
    /// @notice Maps token addresses to their total allocation percentage across all V1 pools
    mapping (address => uint16) public totalAllocation;
    
    /// @notice Maps token addresses to their whitelist status
    mapping (address => bool) public isWhitelistedToken;
    
    /// @notice Maps token addresses to arrays of their associated V1 pool information
    mapping (address => PoolInfo[]) public v1Pools;
    
    /// @notice Maps token addresses to their off-chain balance amounts
    mapping (address => uint256) public offChainBalance;
    
    /// @dev Maps V1 pool IDs to usage status to prevent duplicates
    mapping (string => bool) private _isUsed;
    
    /// @notice PoolInfo struct to store the V1 pool information
    /// @param v1PoolId The V1 pool ID
    /// @param allocation The allocation percentage of the pool
    struct PoolInfo {
        string v1PoolId;
        uint16 allocation;
    }

    /// @notice Claim struct to store the claim information
    /// @param request The V1 request
    /// @param sigR The R value of the signature
    /// @param sigS The S value of the signature
    /// @param sigV The V value of the signature
    struct Claim {
        ICsigmaV1.Request request;
        bytes32 sigR;
        bytes32 sigS;
        uint8 sigV;
    }

    /// @notice Disburse struct to store the disburse information
    /// @param v1PoolIndex The index of the V1 pool
    /// @param amount The amount to disburse
    struct Disburse {
        uint256 v1PoolIndex;
        uint256 amount;
    }

    /// @notice Emitted when admin role is transferred to a new address
    /// @param _oldOwner The previous admin address
    /// @param _newOwner The new admin address
    event AdminTransferred(address _oldOwner, address _newOwner);
    
    /// @notice Emitted when a pool token is added to the whitelist
    /// @param _poolToken The address of the added pool token
    event PoolTokenAdded(address _poolToken);
    
    /// @notice Emitted when a pool token is removed from the whitelist
    /// @param _poolToken The address of the removed pool token
    event PoolTokenRemoved(address _poolToken);
    
    /// @notice Emitted when a V1 pool is added to the fund manager
    /// @param _executor The address that executed the operation
    /// @param _token The underlying token address
    /// @param _allocation The allocation percentage assigned to the pool
    /// @param _v1PoolId The ID of the added V1 pool
    event V1PoolAdded(address indexed _executor, address _token, uint16 _allocation, string _v1PoolId);
    
    /// @notice Emitted when a V1 pool is removed from the fund manager
    /// @param _executor The address that executed the operation
    /// @param _token The underlying token address
    /// @param _allocation The allocation percentage that was removed
    /// @param _v1PoolId The ID of the removed V1 pool
    event V1PoolRemoved(address indexed _executor, address _token, uint16 _allocation, string _v1PoolId);
    
    /// @notice Emitted when a V1 pool's allocation is updated
    /// @param _executor The address that executed the operation
    /// @param _token The underlying token address
    /// @param _prevAllocation The previous allocation percentage
    /// @param _newAllocation The new allocation percentage
    /// @param _v1PoolId The ID of the V1 pool with updated allocation
    event V1PoolAllocationUpdated(
        address indexed _executor,
        address _token,
        uint16 _prevAllocation,
        uint16 _newAllocation,
        string _v1PoolId
    );
    
    /// @notice Emitted when funds are deployed to V1 pools
    /// @param _executor The address that executed the deployment
    /// @param _token The token address of deployed funds
    /// @param _amount The total amount deployed
    event FundDeployed(address indexed _executor, address _token, uint256 _amount);
    
    /// @notice Emitted when funds are claimed from V1 pools
    /// @param _executor The address that executed the claim
    /// @param _token The token address of claimed funds
    /// @param _amount The total amount claimed
    event FundClaimed(address indexed _executor, address _token, uint256 _amount);
    
    /// @notice Emitted when emergency withdrawal is performed
    /// @param _token The token address being withdrawn
    /// @param _to The recipient address
    /// @param _amount The amount withdrawn
    event EmergencyWithdraw(address _token, address _to, uint256 _amount);
    
    /// @notice Emitted when tokens are manually swapped out (sent off-chain)
    /// @param _executor The address that executed the swap
    /// @param _to The recipient address
    /// @param _tokenOut The token being sent out
    /// @param _amountOut The amount sent out
    event SwapOut(
        address indexed _executor,
        address indexed _to,
        address indexed _tokenOut,
        uint256 _amountOut
    );

    /// @notice Emitted when tokens are manually swapped in (received from off-chain)
    /// @param _executor The address that executed the swap
    /// @param _tokenIn The token being received
    /// @param _amountIn The amount received
    /// @param _tokenOut The token being decremented from off-chain balance
    /// @param _amountOut The amount decremented
    event SwapIn(
        address indexed _executor,
        address indexed _tokenIn,
        uint256 _amountIn,
        address indexed _tokenOut,
        uint256 _amountOut
    );

    /// @notice Emitted when a Uniswap V4 swap is executed
    /// @param _executor The address that executed the swap
    /// @param key The pool key used for the swap
    /// @param amountIn The input amount
    /// @param amountOut The output amount received
    event Swap(address indexed _executor, PoolKey key, uint128 amountIn, uint256 amountOut);

    /// @notice Ensures the provided address is not the zero address
    /// @param _account The address to validate
    modifier notZeroAddress(address _account) {
        require(_account != address(0), "address cannot be zero");
        _;
    }

    /// @notice Ensures the caller is the pool manager for the specified token
    /// @param _token The token address to check pool manager for
    modifier onlyPoolManager(address _token) {
        if(_msgSender() != CsigmaV3Pool(pool[_token]).poolManager()) {
            revert AccessDenied(_msgSender());
        }
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @notice Initializes the contract with the required parameters
    /// @param _diamondV1 The address of the V1 diamond
    /// @param _lenderId The lender ID of the fund manager
    /// @param _manager The address of manager multisig
    /// @param _router The address of the Uniswap V4 router
    /// @param _poolManager The address of the Uniswap V4 pool manager
    /// @param _permit2 The address of the Permit2 contract
    function initialize(
        address _diamondV1,
        string calldata _lenderId,
        address _manager,
        address _router,
        address _poolManager,
        address _permit2
    )
        public
        initializer
    {
        __AccessControl_init();
        __UUPSUpgradeable_init();
        __Pausable_init();

        _grantRole(DEFAULT_ADMIN_ROLE, _msgSender());
        _grantRole(ROLE_MANAGER, _manager);
        diamondV1 = _diamondV1;
        fundManagerLenderId = _lenderId;

        router = payable(_router);
        poolManager = IPoolManager(_poolManager);
        permit2 = IPermit2(_permit2);
    }

    /// @notice Returns the total number of V1 pools to which the funds are deployed
    /// @param _token The address of underlying token
    function totalV1Pools(address _token) external view returns (uint256) {
        return v1Pools[_token].length;
    }

    /// @notice Returns the total assets under management
    /// @param _token The address of underlying token
    function totalAssets(address _token) public view virtual returns (uint256) {
        return (IERC20Upgradeable(_token).balanceOf(address(this)) 
                + ICsigmaV1(diamondV1).getTokenBalance(fundManagerLenderId, _token)
                + offChainBalance[_token]
                );
    }

    /// @notice Adds an underlying token of given pool to the whitelist
    /// @param _pool The address of the pool
    function addTokenToWhitelist(address _pool) external onlyRole(ROLE_MANAGER) {
        address _token = CsigmaV3Pool(_pool).poolToken();
        if(_token == address(0) || isWhitelistedToken[_token]) {
            revert InvalidAddress(_token);
        }
        isWhitelistedToken[_token] = true;
        pool[_token] = _pool;
        SafeERC20Upgradeable.forceApprove(IERC20Upgradeable(_token), diamondV1, type(uint256).max);
        emit PoolTokenAdded(_token);
    }

    /// @notice Removes an underlying token of given pool from the whitelist
    /// @param _pool The address of the pool
    function removeTokenFromWhitelist(address _pool) external onlyRole(ROLE_MANAGER) {
        address _token = CsigmaV3Pool(_pool).poolToken();
        if(!isWhitelistedToken[_token]) {
            revert InvalidAddress(_token);
        }
        isWhitelistedToken[_token] = false;
        delete pool[_token];
        emit PoolTokenRemoved(_token);
    }

    /// @notice Adds a new V1 pool to the fund manager
    /// @dev Only the pool manager can call this function
    /// @param _token The address of underlying token
    /// @param _v1PoolId The V1 pool ID
    /// @param _allocation The allocation percentage of the pool
    function addPool(address _token, string calldata _v1PoolId, uint16 _allocation) external onlyPoolManager(_token) whenNotPaused {
        if(!isWhitelistedToken[_token]) revert InvalidAddress(_token);
        if(_isUsed[_v1PoolId]) revert DuplicatePool(_v1PoolId);
        if(ICsigmaV1(diamondV1).getCreditPoolStatus(_v1PoolId) != ICsigmaV1.CreditPoolStatus.ACTIVE) {
            revert V1PoolIsNotActive(_v1PoolId);
        }
        if(ICsigmaV1(diamondV1).getPoolToken(_v1PoolId) != _token) {
            revert InvalidV1Pool(_v1PoolId);
        }
        if(_allocation + totalAllocation[_token] > 10000) {
            revert InvalidAllocation(_allocation, _token);
        }
        v1Pools[_token].push(PoolInfo(_v1PoolId, _allocation));
        totalAllocation[_token] += _allocation;
        _isUsed[_v1PoolId] = true;
        emit V1PoolAdded(_msgSender(), _token, _allocation, _v1PoolId); 
    }

    /// @notice Removes a V1 pool from the fund manager
    /// @dev Only the pool manager can call this function
    /// @param _token The address of underlying token
    /// @param _index The index of the V1 pool
    function removePool(address _token, uint256 _index) external onlyPoolManager(_token) whenNotPaused {
        if(!isWhitelistedToken[_token]) revert InvalidAddress(_token);
        uint256 _lastIndex = v1Pools[_token].length - 1;
        PoolInfo memory _pool = v1Pools[_token][_index];
        if(_index != _lastIndex) {
            v1Pools[_token][_index] = v1Pools[_token][_lastIndex];
        }
        v1Pools[_token].pop();
        _isUsed[_pool.v1PoolId] = false;
        totalAllocation[_token] -= _pool.allocation;
        emit V1PoolRemoved(_msgSender(), _token, _pool.allocation, _pool.v1PoolId);
    }

    /// @notice Updates the allocation of a V1 pool
    /// @dev Only the pool manager can call this function
    /// @param _token The address of underlying token
    /// @param _index The index of the V1 pool
    /// @param _allocation The new allocation percentage of the pool
    function updatePoolAllocation(address _token, uint256 _index, uint16 _allocation) external onlyPoolManager(_token) whenNotPaused {
        if(!isWhitelistedToken[_token]) revert InvalidAddress(_token);
        PoolInfo memory _pool = v1Pools[_token][_index];
        if(((_allocation + totalAllocation[_token]) - _pool.allocation) > 10000) {
            revert InvalidAllocation(_allocation, _token);
        }
        v1Pools[_token][_index].allocation = _allocation; 
        totalAllocation[_token] = (_allocation + totalAllocation[_token]) - _pool.allocation;
        emit V1PoolAllocationUpdated(_msgSender(), _token, _pool.allocation, _allocation, _pool.v1PoolId);
    }

    /// @notice Deploys the funds to the V1 pools
    /// @param _token The address of underlying token
    /// @dev Only the pool manager can call this function
    function deployFunds(address _token) external onlyPoolManager(_token) whenNotPaused {
        if(!isWhitelistedToken[_token]) revert InvalidAddress(_token);
        if(totalAllocation[_token] != 10000) revert InvalidAllocation(totalAllocation[_token], _token);
        uint256 _bal = IERC20Upgradeable(_token).balanceOf(address(this));
        ICsigmaV1(diamondV1).deposit(fundManagerLenderId, _token, _bal);
        uint256 _amount;
        uint256 _deployed;
        for(uint i; i < v1Pools[_token].length; i++) {
            _amount = (_bal * v1Pools[_token][i].allocation) / 10000;
            _deployed += _amount;
            ICsigmaV1(diamondV1).invest(fundManagerLenderId, v1Pools[_token][i].v1PoolId, _amount);
        }
        CsigmaV3Pool(pool[_token]).updateAssetUnderManagement(CsigmaV3Pool(pool[_token]).assetUnderManagement() + _deployed);
        emit FundDeployed(_msgSender(), _token, _bal);
    }

    /// @notice Claims the funds from the V1 pools
    /// @dev Only the pool manager can call this function
    /// @param _token The address of underlying token
    /// @param _claim The claim information
    function claimFunds(address _token, Claim[] calldata _claim) external onlyPoolManager(_token) whenNotPaused {
        if(!isWhitelistedToken[_token]) revert InvalidAddress(_token);
        uint256 _initial = ICsigmaV1(diamondV1).getTokenBalance(fundManagerLenderId, _token);
        for(uint i; i < _claim.length; i++) {
            ICsigmaV1(diamondV1).withdrawPoolPaymentIntoVault(
                _claim[i].request,
                _claim[i].sigR,
                _claim[i].sigS,
                _claim[i].sigV
            );
        }
        uint256 _recouped = ICsigmaV1(diamondV1).getTokenBalance(fundManagerLenderId, _token);
        CsigmaV3Pool(pool[_token]).updateAssetUnderManagement(CsigmaV3Pool(pool[_token]).assetUnderManagement() - (_recouped - _initial));
        ICsigmaV1(diamondV1).withdrawRequest(fundManagerLenderId, _token, _recouped);
        emit FundClaimed(_msgSender(), _token, _recouped);
    }
    
    /// @notice Sends the funds to the V2 pool reserve and repays the pending queue
    /// @dev Only the pool manager can call this function
    /// @param _token The address of underlying token
    /// @param _v2Amount The amount to send to the V2 pool reserve
    function sendToV2Reserve(address _token, uint256 _v2Amount, uint256 uptoQueuePosition) external onlyPoolManager(_token) whenNotPaused {
        if(!isWhitelistedToken[_token]) revert InvalidAddress(_token);
        SafeERC20Upgradeable.safeTransfer(IERC20Upgradeable(_token), pool[_token], _v2Amount);
        address withdrawManager = CsigmaV3Pool(pool[_token]).withdrawalManager();
        if(withdrawManager == address(0)) return;
        WithdrawManager(withdrawManager).repay(uptoQueuePosition, _v2Amount);
    }

    /// @notice Manually swaps tokens out to an external address (for off-chain operations)
    /// @dev Only the pool manager can call this function
    /// @dev Increases the off-chain balance tracking for the token
    /// @param _tokenOut The address of the token being sent out
    /// @param _to The recipient address
    /// @param _amountOut The amount being sent out
    function manualSwapOut(address _tokenOut, address _to, uint256 _amountOut) external onlyPoolManager(_tokenOut) whenNotPaused {
        if(!isWhitelistedToken[_tokenOut]) revert InvalidAddress(_tokenOut);
        SafeERC20Upgradeable.safeTransfer(IERC20Upgradeable(_tokenOut), _to, _amountOut);
        offChainBalance[_tokenOut] += _amountOut;
        emit SwapOut(_msgSender(), _to, _tokenOut, _amountOut);
    }

    /// @notice Manually swaps tokens in from an external source (from off-chain operations)
    /// @dev Only the pool manager can call this function
    /// @dev Decreases the off-chain balance tracking for the output token
    /// @param _tokenIn The address of the token being received
    /// @param _amountIn The amount being received
    /// @param _tokenOut The address of the token being decremented from off-chain balance
    /// @param _amountOut The amount being decremented from off-chain balance
    function manualSwapIn(
        address _tokenIn,
        uint256 _amountIn,
        address _tokenOut,
        uint256 _amountOut
    ) external onlyPoolManager(_tokenOut) whenNotPaused {
        if(!isWhitelistedToken[_tokenIn]) revert InvalidAddress(_tokenIn);
        SafeERC20Upgradeable.safeTransferFrom(IERC20Upgradeable(_tokenIn), _msgSender(), address(this), _amountIn);
        offChainBalance[_tokenOut] -= _amountOut;
        emit SwapIn(_msgSender(), _tokenIn, _amountIn, _tokenOut, _amountOut);
    }

    /// @notice Executes a single exact input swap on Uniswap V4
    /// @dev Only the pool manager can call this function
    /// @dev Uses Universal Router with Permit2 for gasless approvals
    /// @param key The pool key containing currency pair and fee information
    /// @param amountIn The exact amount of input tokens to swap
    /// @param minAmountOut The minimum amount of output tokens expected
    /// @param inputToken The address of the input token
    /// @return amountOut The actual amount of output tokens received
    function swapExactInputSingle(
        PoolKey calldata key,
        uint128 amountIn,
        uint128 minAmountOut,
        address inputToken
    ) external onlyPoolManager(inputToken) whenNotPaused returns (uint256 amountOut) {
        if(!isWhitelistedToken[inputToken]) revert InvalidAddress(inputToken);
        IERC20(inputToken).approve(address(permit2), amountIn);
        permit2.approve(inputToken, address(router), amountIn, type(uint48).max);

        // Encode the Universal Router command
        bytes memory commands = abi.encodePacked(uint8(Commands.V4_SWAP));
        bytes[] memory inputs = new bytes[](1);

        // Encode V4Router actions
        bytes memory actions = abi.encodePacked(
            uint8(Actions.SWAP_EXACT_IN_SINGLE),
            uint8(Actions.SETTLE_ALL),
            uint8(Actions.TAKE_ALL)
        );

        // Prepare parameters for each action
        bytes[] memory params = new bytes[](3);
        params[0] = abi.encode(
            IV4Router.ExactInputSingleParams({
                poolKey: key,
                zeroForOne: true,
                amountIn: amountIn,
                amountOutMinimum: minAmountOut,
                hookData: bytes("")
            })
        );
        params[1] = abi.encode(key.currency0, amountIn);
        params[2] = abi.encode(key.currency1, minAmountOut);

        // Combine actions and params into inputs
        inputs[0] = abi.encode(actions, params);

        // Execute the swap
        uint256 deadline = block.timestamp + 20;
        IUniversalRouter(router).execute(commands, inputs, deadline);

        // Verify and return the output amount
        amountOut = key.currency1.balanceOf(address(this));
        require(amountOut >= minAmountOut, "Insufficient output amount");
        emit Swap(_msgSender(), key, amountIn, amountOut);
        return amountOut;
    }

    /// @notice Pauses the contract
    /// @dev Only the admin can call this function
    function pause() external onlyRole(ROLE_MANAGER) {
        _pause();
    }

    /// @notice Unpauses the contract
    /// @dev Only the admin can call this function
    function unpause() external onlyRole(ROLE_MANAGER) {
        _unpause();
    }

    /// @notice Withdraws the funds from the contract
    /// @dev Only the admin can call this function
    /// @param _token The address of the token
    /// @param _to The address to which the funds are withdrawn
    /// @param _amount The amount to withdraw
    function emergencyWithdraw(address _token, address _to, uint256 _amount) external onlyRole(DEFAULT_ADMIN_ROLE) {
        SafeERC20Upgradeable.safeTransfer(IERC20Upgradeable(_token), _to, _amount);
        emit EmergencyWithdraw(_token, _to, _amount);
    }

    /// @notice Transfers the admin role to a new address
    /// @param _newOwner The address of the new admin
    function transferAdmin(address _newOwner) public
    {
        grantRole(DEFAULT_ADMIN_ROLE, _newOwner);
        revokeRole(DEFAULT_ADMIN_ROLE, _msgSender());
        emit AdminTransferred(_msgSender(), _newOwner);
    }    

    /// @notice Grants the given role to the account
    /// @param role The role to grant
    /// @param _account The address to which the role is granted
    function grantRole(bytes32 role, address _account)
        public
        virtual
        override
        onlyRole(getRoleAdmin(role))
        notZeroAddress(_account)
        whenNotPaused
    {
        _grantRole(role, _account);
    }

    /// @notice Revokes the given role from the account
    /// @param role The role to revoke
    /// @param _account The address from which the role is revoked
    function revokeRole(bytes32 role, address _account)
        public
        override
        onlyRole(getRoleAdmin(role))        
        notZeroAddress(_account)        
        whenNotPaused
    {
        _revokeRole(role, _account);
    }

    /// @notice Upgrades the contract to a new implementation
    /// @dev Only the admin can call this function
    /// @param _newImplementation The address of the new implementation
    function _authorizeUpgrade(address _newImplementation)
        internal
        override
        onlyRole(DEFAULT_ADMIN_ROLE)
    {}
}

